"""
Invoice validation, event sorting, and amount summarization utilities.
"""

from typing import Any, Dict, List, Optional, Union
import datetime


def is_valid_invoice_id(invoice_id: Any) -> bool:
    """Check if invoice_id is a non-empty string."""
    return isinstance(invoice_id, str) and len(invoice_id) > 0


def is_valid_amount(amount: Any) -> bool:
    """Check if amount is a non-negative number."""
    return isinstance(amount, (int, float)) and amount >= 0


def is_valid_date(date_str: Any) -> bool:
    """Check if date_str is a valid ISO format date string."""
    if not isinstance(date_str, str):
        return False
    try:
        datetime.datetime.fromisoformat(date_str)
        return True
    except ValueError:
        return False


def is_valid_currency(currency: Any) -> bool:
    """Check if currency is a 3-letter uppercase string."""
    return isinstance(currency, str) and len(currency) == 3 and currency.isupper()


def is_valid_status(status: Any) -> bool:
    """Check if status is one of the allowed values."""
    return status in ("draft", "sent", "paid", "overdue", "cancelled")


def has_required_fields(invoice: Dict[str, Any]) -> bool:
    """Check if invoice has all required fields."""
    required = {"id", "amount", "date", "currency", "status"}
    return required.issubset(invoice.keys())


def validate_invoice(invoice: Dict[str, Any]) -> bool:
    """Validate an invoice dictionary completely."""
    if not isinstance(invoice, dict):
        return False
    if not has_required_fields(invoice):
        return False
    if not is_valid_invoice_id(invoice["id"]):
        return False
    if not is_valid_amount(invoice["amount"]):
        return False
    if not is_valid_date(invoice["date"]):
        return False
    if not is_valid_currency(invoice["currency"]):
        return False
    if not is_valid_status(invoice["status"]):
